-- CLOSED current-family loader; host authenticates independent parent/child/tail
-- factory handles. Hash/caller/xid describe SQL correspondence, not byte authority.
-- No runtime grant, processing admission, reopen, or normal registry activation.
CREATE SCHEMA wm_current_app_load;
REVOKE ALL ON SCHEMA wm_current_app_load FROM PUBLIC;
CREATE TABLE wm_current_app_load.target (
 singleton boolean PRIMARY KEY CHECK(singleton), catalog_hash text NOT NULL CHECK(catalog_hash ~ '^[a-f0-9]{64}$'),
 nonce uuid NOT NULL, incarnation uuid NOT NULL, generation_id uuid NOT NULL,
 control_revision bigint NOT NULL CHECK(control_revision>0), state text NOT NULL CHECK(state='CLOSED')
);
CREATE TABLE wm_current_app_load.descriptor (
 run_id uuid PRIMARY KEY, owner_xid bigint NOT NULL, descriptor jsonb NOT NULL,
 target_nonce uuid NOT NULL, target_incarnation uuid NOT NULL, target_generation uuid NOT NULL,
 expected_control_revision bigint NOT NULL, expected_count integer NOT NULL CHECK(expected_count BETWEEN 1 AND 5000),
 expected_census jsonb NOT NULL, expected_digest text NOT NULL CHECK(expected_digest ~ '^[a-f0-9]{64}$'),
 athlete_id text NOT NULL, sealed boolean NOT NULL DEFAULT false, loading boolean NOT NULL DEFAULT false,
 loaded boolean NOT NULL DEFAULT false, post_replayed boolean NOT NULL DEFAULT false, finished boolean NOT NULL DEFAULT false
);
CREATE TABLE wm_current_app_load.row_stage (
 run_id uuid NOT NULL REFERENCES wm_current_app_load.descriptor(run_id), ordinal integer NOT NULL CHECK(ordinal BETWEEN 1 AND 5000),
 relation_name text NOT NULL, physical_row jsonb NOT NULL, row_digest text NOT NULL CHECK(row_digest ~ '^[a-f0-9]{64}$'),
 primary_key jsonb NOT NULL, bytes integer NOT NULL CHECK(bytes BETWEEN 1 AND 4194304), consumed boolean NOT NULL DEFAULT false,
 PRIMARY KEY(run_id,ordinal), UNIQUE(run_id,relation_name,primary_key)
);
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['target','descriptor','row_stage'] LOOP
  EXECUTE format('ALTER TABLE wm_current_app_load.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('ALTER TABLE wm_current_app_load.%I FORCE ROW LEVEL SECURITY',t);
  EXECUTE format('CREATE POLICY live_owner ON wm_current_app_load.%I USING(current_user=pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=%L::regclass))) WITH CHECK(current_user=pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=%L::regclass)))',t,'wm_current_app_load.'||t,'wm_current_app_load.'||t);
 END LOOP;
END $$;
REVOKE ALL ON ALL TABLES IN SCHEMA wm_current_app_load FROM PUBLIC;
CREATE FUNCTION wm_current_app_load.owner_check() RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
DECLARE own name:=pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid='wm_current_app_load.target'::regclass)); BEGIN
 IF session_user<>own OR current_user<>own OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname=own AND (rolsuper OR rolbypassrls))
 OR own<>pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid='public.restore_processing_admission'::regclass))
 OR own<>pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid='public.manual_race_evidence_v2'::regclass))
 THEN RAISE EXCEPTION 'CURRENT_LOAD_OWNER_REQUIRED' USING ERRCODE='42501'; END IF;
END $$;
CREATE FUNCTION wm_current_app_load.hash_json(v jsonb) RETURNS text LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $$ SELECT encode(sha256(convert_to(v::text,'UTF8')),'hex') $$;
