CREATE FUNCTION wm_current_app_load.relation(t text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$ DECLARE r jsonb; BEGIN
 SELECT value INTO r FROM jsonb_array_elements(wm_current_app_load.relation_profile()) WHERE value->>'relation'=t;
 IF r IS NULL THEN RAISE EXCEPTION 'CURRENT_LOAD_RELATION_REJECTED'; END IF; RETURN r;
END $$;

CREATE FUNCTION wm_current_app_load.assert_profile() RETURNS text
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
DECLARE p jsonb; actual jsonb; pk text; own name; BEGIN
 PERFORM wm_current_app_load.owner_check();
 FOR p IN SELECT value FROM jsonb_array_elements(wm_current_app_load.relation_profile()) LOOP
  SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull) ORDER BY a.attnum),pg_get_userbyid(c.relowner)
   INTO actual,own FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped
   WHERE n.nspname=p->>'schema' AND c.relname=p->>'table' GROUP BY c.relowner;
  SELECT pg_get_constraintdef(c.oid) INTO pk FROM pg_constraint c WHERE c.conrelid=format('%I.%I',p->>'schema',p->>'table')::regclass AND c.contype='p';
  IF actual IS DISTINCT FROM p->'columns' OR pk IS DISTINCT FROM p->>'primaryKey'
   OR own IS DISTINCT FROM session_user THEN RAISE EXCEPTION 'CURRENT_LOAD_PROFILE_REJECTED'; END IF;
 END LOOP;
 RETURN wm_current_app_load.hash_json(wm_current_app_load.relation_profile());
END $$;
CREATE FUNCTION wm_current_app_load.configure_target() RETURNS jsonb
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
DECLARE c public.restore_processing_admission; h text; BEGIN
 PERFORM wm_current_app_load.owner_check();
 PERFORM pg_advisory_xact_lock(77210,1);
 SELECT * INTO STRICT c FROM public.restore_processing_admission WHERE singleton FOR UPDATE;
 IF c.state<>'CLOSED' THEN RAISE EXCEPTION 'CURRENT_LOAD_CLOSED_REQUIRED'; END IF;
 IF c.target_nonce IS NULL OR c.target_incarnation IS NULL THEN RAISE EXCEPTION 'CURRENT_LOAD_TARGET_BINDING_REQUIRED'; END IF;
 h:=wm_current_app_load.assert_profile();
 IF EXISTS(SELECT 1 FROM wm_current_app_load.target) THEN RAISE EXCEPTION 'CURRENT_LOAD_TARGET_ALREADY_CONFIGURED'; END IF;
 INSERT INTO wm_current_app_load.target VALUES(true,h,c.target_nonce,c.target_incarnation,c.generation_id,c.local_revision,'CLOSED');
 RETURN jsonb_build_object('catalogHash',h,'nonce',c.target_nonce,'incarnation',c.target_incarnation,'generationId',c.generation_id,'controlRevision',c.local_revision::text,'state','CLOSED');
END $$;
CREATE FUNCTION wm_current_app_load.assert_context(run uuid) RETURNS wm_current_app_load.descriptor
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
DECLARE d wm_current_app_load.descriptor; t wm_current_app_load.target; c jsonb; BEGIN
 PERFORM wm_current_app_load.owner_check();
 SELECT * INTO STRICT d FROM wm_current_app_load.descriptor WHERE run_id=run;
 c:=public.assert_restore_processing_closed(d.expected_control_revision,d.target_nonce,d.target_incarnation);
 SELECT * INTO STRICT t FROM wm_current_app_load.target WHERE singleton FOR UPDATE;
 IF d.owner_xid<>txid_current() OR t.state<>'CLOSED' OR d.target_nonce<>t.nonce OR d.target_incarnation<>t.incarnation
  OR d.target_generation<>t.generation_id OR c->>'generationId' IS DISTINCT FROM t.generation_id::text
  OR d.athlete_id IS DISTINCT FROM nullif(current_setting('app.athlete_id',true),'')
  OR t.catalog_hash<>wm_current_app_load.assert_profile() THEN RAISE EXCEPTION 'CURRENT_LOAD_CONTEXT_REJECTED'; END IF;
 RETURN d;
END $$;
CREATE FUNCTION wm_current_app_load.begin_stage(run uuid,description jsonb) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
DECLARE t wm_current_app_load.target; p jsonb; tenant text; n bigint; BEGIN
 PERFORM wm_current_app_load.owner_check();
 PERFORM public.manual_race_v2_assert_json_bound(description);
 SELECT * INTO STRICT t FROM wm_current_app_load.target WHERE singleton;
 PERFORM public.assert_restore_processing_closed(t.control_revision,t.nonce,t.incarnation);
 IF jsonb_typeof(description)<>'object' OR description-ARRAY['profileVersion','source','parentArtifactDigest','childArtifactDigest','tailWitnessDigest','originalRowsDigest','athleteId','expectedCount','expectedCensus','expectedRowsDigest','target']<>'{}'::jsonb
  OR NOT(description ?& ARRAY['profileVersion','source','parentArtifactDigest','childArtifactDigest','tailWitnessDigest','originalRowsDigest','athleteId','expectedCount','expectedCensus','expectedRowsDigest','target'])
  OR description->>'profileVersion' IS DISTINCT FROM '1' OR jsonb_typeof(description->'source') IS DISTINCT FROM 'object'
  OR (description->'source')-ARRAY['systemIdentifier','databaseOid','captureId','generationId','registrySha256','catalogSha256','baselineThroughLsn']<>'{}'::jsonb
  OR NOT(description->'source' ?& ARRAY['systemIdentifier','databaseOid','captureId','generationId','registrySha256','catalogSha256','baselineThroughLsn'])
  OR description->'target' IS DISTINCT FROM jsonb_build_object('catalogHash',t.catalog_hash,'nonce',t.nonce,'incarnation',t.incarnation,'generationId',t.generation_id,'controlRevision',t.control_revision::text,'state','CLOSED')
  OR description->>'athleteId' IS DISTINCT FROM nullif(current_setting('app.athlete_id',true),'')
  OR coalesce(description->>'athleteId','')='' OR (description->>'expectedCount') !~ '^[1-9][0-9]*$'
  OR (description->>'expectedCount')::numeric>5000
 THEN RAISE EXCEPTION 'CURRENT_LOAD_DESCRIPTOR_REJECTED'; END IF;
 IF coalesce(description->'source'->>'systemIdentifier','') !~ '^[1-9][0-9]{0,19}$' OR (description->'source'->>'systemIdentifier')::numeric>18446744073709551615
  OR coalesce(description->'source'->>'databaseOid','') !~ '^[1-9][0-9]*$' OR (description->'source'->>'databaseOid')::numeric>4294967295
  OR coalesce(description->'source'->>'captureId','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  OR coalesce(description->'source'->>'generationId','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  OR coalesce(description->'source'->>'registrySha256','') !~ '^[a-f0-9]{64}$' OR coalesce(description->'source'->>'catalogSha256','') !~ '^[a-f0-9]{64}$'
  OR coalesce(description->'source'->>'baselineThroughLsn','') !~ '^[0-9A-F]{1,8}/[0-9A-F]{1,8}$' THEN RAISE EXCEPTION 'CURRENT_LOAD_SOURCE_DESCRIPTOR_REJECTED'; END IF;
 FOREACH tenant IN ARRAY ARRAY['parentArtifactDigest','childArtifactDigest','tailWitnessDigest','originalRowsDigest','expectedRowsDigest'] LOOP
  IF coalesce(description->>tenant,'') !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'CURRENT_LOAD_DESCRIPTOR_REJECTED'; END IF;
 END LOOP;
 IF jsonb_typeof(description->'expectedCensus')<>'object' OR (SELECT count(*) FROM jsonb_object_keys(description->'expectedCensus'))<>110 THEN RAISE EXCEPTION 'CURRENT_LOAD_CENSUS_REJECTED'; END IF;
 n:=0;
 FOR p IN SELECT value FROM jsonb_array_elements(wm_current_app_load.relation_profile()) LOOP
  IF NOT(description->'expectedCensus' ? (p->>'relation')) OR description->'expectedCensus'->>(p->>'relation') !~ '^(0|[1-9][0-9]*)$'
   OR (description->'expectedCensus'->>(p->>'relation'))::numeric>5000 THEN RAISE EXCEPTION 'CURRENT_LOAD_CENSUS_REJECTED'; END IF;
  n:=n+(description->'expectedCensus'->>(p->>'relation'))::bigint;
 END LOOP;
 IF n<>(description->>'expectedCount')::bigint OR description->'expectedCensus'->>'manual_race_v2_live_transition'<>'0' THEN RAISE EXCEPTION 'CURRENT_LOAD_CENSUS_REJECTED'; END IF;
 tenant:=description->>'athleteId';
 IF EXISTS(SELECT 1 FROM wm_current_app_load.descriptor prior WHERE prior.owner_xid=txid_current() AND public.nutrition_copy_utf16_key(prior.athlete_id)>=public.nutrition_copy_utf16_key(tenant)) THEN RAISE EXCEPTION 'CURRENT_LOAD_SORTED_TENANTS_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(tenant,77206)); PERFORM pg_advisory_xact_lock(hashtextextended(tenant,0));
 INSERT INTO wm_current_app_load.descriptor(run_id,owner_xid,descriptor,target_nonce,target_incarnation,target_generation,expected_control_revision,expected_count,expected_census,expected_digest,athlete_id)
 VALUES(run,txid_current(),description,t.nonce,t.incarnation,t.generation_id,t.control_revision,n,description->'expectedCensus',description->>'expectedRowsDigest',tenant);
END $$;
CREATE FUNCTION wm_current_app_load.encode_row(t text,v jsonb) RETURNS jsonb
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' SET DateStyle='ISO,YMD' AS $$
DECLARE p jsonb; c jsonb; q text:=''; expression text; body jsonb; BEGIN
 p:=wm_current_app_load.relation(t);
 IF jsonb_typeof(v)<>'object' OR octet_length(v::text)>4194304 THEN RAISE EXCEPTION 'CURRENT_LOAD_ROW_REJECTED'; END IF;
 IF (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(v) key) IS DISTINCT FROM (SELECT array_agg(x->>'name' ORDER BY x->>'name') FROM jsonb_array_elements(p->'columns') x) THEN RAISE EXCEPTION 'CURRENT_LOAD_COLUMN_REJECTED'; END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(p->'columns') LOOP
  expression:=format('r.%I',c->>'name');
  IF c->>'type'='timestamp with time zone' THEN expression:=format('to_char(r.%I AT TIME ZONE ''UTC'',''YYYY-MM-DD"T"HH24:MI:SS.US"Z"'')',c->>'name');
  ELSIF c->>'type' IN ('bigint','name','numeric') THEN expression:=expression||'::text'; END IF;
  q:=q||CASE WHEN q='' THEN '' ELSE ',' END||format('%L,%s',c->>'name',expression);
 END LOOP;
 EXECUTE format('SELECT jsonb_build_object(%s) FROM jsonb_populate_record(NULL::%I.%I,$1) r',q,p->>'schema',p->>'table') INTO body USING v;
 RETURN body;
END $$;
CREATE FUNCTION wm_current_app_load.physical_row(t text,v jsonb) RETURNS jsonb
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$ DECLARE body jsonb; BEGIN
 body:=wm_current_app_load.encode_row(t,v);
 IF body IS DISTINCT FROM v THEN RAISE EXCEPTION 'CURRENT_LOAD_PHYSICAL_ENCODING_REJECTED'; END IF;
 RETURN body;
END $$;
CREATE FUNCTION wm_current_app_load.stage_row(run uuid,p_ordinal integer,t text,v jsonb,row_hash text) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
DECLARE d wm_current_app_load.descriptor; p jsonb; body jsonb; pk jsonb; n bigint; keys text[]; BEGIN
 d:=wm_current_app_load.assert_context(run); p:=wm_current_app_load.relation(t);
 PERFORM public.manual_race_v2_assert_json_bound(v); body:=wm_current_app_load.physical_row(t,v);
 IF d.sealed OR p_ordinal<1 OR p_ordinal>d.expected_count OR v->>'athlete_id' IS DISTINCT FROM d.athlete_id
  OR wm_current_app_load.hash_json(body) IS DISTINCT FROM row_hash OR t='manual_race_v2_live_transition'
 THEN RAISE EXCEPTION 'CURRENT_LOAD_ROW_REJECTED'; END IF;
 SELECT array_agg(a.attname ORDER BY k.n) INTO keys FROM pg_constraint c CROSS JOIN LATERAL unnest(c.conkey) WITH ORDINALITY k(attnum,n)
 JOIN pg_attribute a ON a.attrelid=c.conrelid AND a.attnum=k.attnum WHERE c.conrelid=format('%I.%I',p->>'schema',p->>'table')::regclass AND c.contype='p';
 SELECT jsonb_agg(body->a.key ORDER BY a.n) INTO pk FROM unnest(keys) WITH ORDINALITY a(key,n);
 SELECT coalesce(sum(bytes),0) INTO n FROM wm_current_app_load.row_stage WHERE run_id=run;
 IF n+octet_length(body::text)>16777216 THEN RAISE EXCEPTION 'CURRENT_LOAD_BODY_LIMIT'; END IF;
 INSERT INTO wm_current_app_load.row_stage VALUES(run,p_ordinal,t,body,row_hash,pk,octet_length(body::text),false);
END $$;

CREATE FUNCTION wm_current_app_load.seal_stage(run uuid) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
DECLARE d wm_current_app_load.descriptor; p jsonb; n bigint; h text; BEGIN
 d:=wm_current_app_load.assert_context(run);
 IF d.sealed THEN RAISE EXCEPTION 'CURRENT_LOAD_ALREADY_SEALED'; END IF;
 SELECT count(*),wm_current_app_load.hash_json(jsonb_agg(jsonb_build_object('ordinal',ordinal,'relation',relation_name,'rowDigest',row_digest) ORDER BY ordinal)) INTO n,h FROM wm_current_app_load.row_stage WHERE run_id=run;
 IF n<>d.expected_count OR h IS DISTINCT FROM d.expected_digest
  OR (SELECT min(ordinal) FROM wm_current_app_load.row_stage WHERE run_id=run)<>1
  OR (SELECT max(ordinal) FROM wm_current_app_load.row_stage WHERE run_id=run)<>n
 THEN RAISE EXCEPTION 'CURRENT_LOAD_FULL_CENSUS_REJECTED'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(wm_current_app_load.relation_profile()) LOOP
  SELECT count(*) INTO n FROM wm_current_app_load.row_stage WHERE run_id=run AND relation_name=p->>'relation';
  IF n IS DISTINCT FROM (d.expected_census->>(p->>'relation'))::bigint THEN RAISE EXCEPTION 'CURRENT_LOAD_RELATION_CENSUS_REJECTED'; END IF;
 END LOOP;
 SELECT wm_current_app_load.hash_json(coalesce(jsonb_agg(jsonb_build_object('ordinal',ordinal,'rowDigest',row_digest) ORDER BY ordinal),'[]'::jsonb)) INTO h
  FROM wm_current_app_load.row_stage WHERE run_id=run AND relation_name='restore_suppression_event';
 IF h IS DISTINCT FROM d.descriptor->>'originalRowsDigest' THEN RAISE EXCEPTION 'CURRENT_LOAD_ORIGINAL_CENSUS_REJECTED'; END IF;
 UPDATE wm_current_app_load.descriptor SET sealed=true WHERE run_id=run;
END $$;
-- Called only from explicitly enumerated successor INSERT trigger branches.
-- Presence of any source row/JSON/hash does not authorize runtime or admission.
CREATE FUNCTION wm_current_app_load.exact_loading_row(p_schema text,p_table text,v jsonb) RETURNS boolean
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
DECLARE d wm_current_app_load.descriptor; t text; encoded jsonb; BEGIN
 IF session_user IS DISTINCT FROM pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid='wm_current_app_load.target'::regclass)) OR current_user IS DISTINCT FROM session_user THEN RETURN false; END IF;
 SELECT * INTO d FROM wm_current_app_load.descriptor WHERE owner_xid=txid_current() AND athlete_id=nullif(current_setting('app.athlete_id',true),'') AND sealed AND loading AND NOT loaded AND NOT finished;
 IF NOT FOUND THEN RETURN false; END IF;
 d:=wm_current_app_load.assert_context(d.run_id);
 t:=CASE WHEN p_schema='public' THEN p_table ELSE p_schema||'.'||p_table END;
 encoded:=wm_current_app_load.encode_row(t,v);
 IF NOT EXISTS(SELECT 1 FROM wm_current_app_load.row_stage s WHERE s.run_id=d.run_id AND s.relation_name=t AND s.physical_row=encoded AND s.row_digest=wm_current_app_load.hash_json(encoded)) THEN RAISE EXCEPTION 'CURRENT_LOAD_UNSTAGED_ROW_REJECTED'; END IF;
 RETURN true;
END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA wm_current_app_load FROM PUBLIC;

