);
ALTER TABLE wm_current_app_load.successor_metadata ENABLE ROW LEVEL SECURITY;
ALTER TABLE wm_current_app_load.successor_metadata FORCE ROW LEVEL SECURITY;
CREATE POLICY metadata_owner ON wm_current_app_load.successor_metadata USING(current_user=pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid='wm_current_app_load.successor_metadata'::regclass))) WITH CHECK(current_user=pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid='wm_current_app_load.successor_metadata'::regclass)));
