-- A descriptor must survive deferred validation and COMMIT. Never remove it to
-- avoid a pending trigger. These state transitions cannot edit authenticated rows.
CREATE FUNCTION wm_current_app_load.guard_inventory() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$ BEGIN
 PERFORM wm_current_app_load.owner_check();
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'CURRENT_LOAD_INVENTORY_IMMUTABLE'; END IF;
 IF TG_TABLE_NAME='descriptor' THEN
  IF TG_OP='INSERT' AND (NEW.owner_xid<>txid_current() OR NEW.sealed OR NEW.loading OR NEW.loaded OR NEW.post_replayed OR NEW.finished) THEN RAISE EXCEPTION 'CURRENT_LOAD_XID_REJECTED'; END IF;
  IF TG_OP='UPDATE' AND (OLD.owner_xid<>txid_current() OR
   to_jsonb(OLD)-ARRAY['sealed','loading','loaded','post_replayed','finished'] IS DISTINCT FROM to_jsonb(NEW)-ARRAY['sealed','loading','loaded','post_replayed','finished']
   OR OLD.finished OR (OLD.sealed AND NOT NEW.sealed) OR (OLD.loaded AND NOT NEW.loaded) OR (OLD.post_replayed AND NOT NEW.post_replayed)
   OR (NEW.loading AND NOT NEW.sealed) OR (NOT NEW.loading AND OLD.loading AND NOT NEW.finished) OR (NEW.post_replayed AND NOT NEW.loaded) OR (NEW.finished AND NOT NEW.post_replayed))
  THEN RAISE EXCEPTION 'CURRENT_LOAD_INVENTORY_IMMUTABLE'; END IF;
 ELSIF TG_TABLE_NAME='row_stage' THEN
  IF TG_OP='INSERT' THEN
   PERFORM wm_current_app_load.assert_context(NEW.run_id);
   IF EXISTS(SELECT 1 FROM wm_current_app_load.descriptor d WHERE d.run_id=NEW.run_id AND (d.sealed OR d.loading OR NEW.ordinal>d.expected_count OR NEW.physical_row->>'athlete_id' IS DISTINCT FROM d.athlete_id))
    OR NEW.bytes IS DISTINCT FROM octet_length(NEW.physical_row::text)
    OR (SELECT coalesce(sum(s.bytes),0) FROM wm_current_app_load.row_stage s WHERE s.run_id=NEW.run_id)+NEW.bytes>16777216
    OR NEW.consumed OR wm_current_app_load.hash_json(wm_current_app_load.physical_row(NEW.relation_name,NEW.physical_row)) IS DISTINCT FROM NEW.row_digest
    OR NEW.relation_name='manual_race_v2_live_transition'
   THEN RAISE EXCEPTION 'CURRENT_LOAD_ROW_REJECTED'; END IF;
  END IF;
  IF TG_OP='UPDATE' AND (to_jsonb(OLD)-'consumed' IS DISTINCT FROM to_jsonb(NEW)-'consumed' OR OLD.consumed OR NOT NEW.consumed) THEN RAISE EXCEPTION 'CURRENT_LOAD_INVENTORY_IMMUTABLE'; END IF;
 ELSE
  IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'CURRENT_LOAD_INVENTORY_IMMUTABLE'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER current_descriptor_guard BEFORE INSERT OR UPDATE OR DELETE ON wm_current_app_load.descriptor FOR EACH ROW EXECUTE FUNCTION wm_current_app_load.guard_inventory();
CREATE TRIGGER current_stage_guard BEFORE INSERT OR UPDATE OR DELETE ON wm_current_app_load.row_stage FOR EACH ROW EXECUTE FUNCTION wm_current_app_load.guard_inventory();
CREATE TRIGGER current_metadata_guard BEFORE UPDATE OR DELETE ON wm_current_app_load.successor_metadata FOR EACH ROW EXECUTE FUNCTION wm_current_app_load.guard_inventory();
CREATE TRIGGER current_target_guard BEFORE UPDATE OR DELETE ON wm_current_app_load.target FOR EACH ROW EXECUTE FUNCTION wm_current_app_load.guard_inventory();
CREATE TRIGGER current_historical_seal_guard BEFORE UPDATE OR DELETE ON wm_current_app_load.historical_seal FOR EACH ROW EXECUTE FUNCTION wm_current_app_load.guard_inventory();

-- Preserve installed old branches and all function owner/config/ACL attributes.
-- Exact current row branches never run for normal runtime, UPDATE or DELETE.
DO $successors$ DECLARE signature text; expected_hash text; oid_value oid;
