BEGIN
 FOR signature,expected_hash IN SELECT * FROM (VALUES ('public.activity_track_ingestion_allowed()','5606d1733a7f35a06fc36e35141148d1ac014e33adcc418cc04f9b8f0b1ddd0e'),('public.bump_integrated_dependency_head()','5760c96bd93f5ad515ba07f271b52624532842b2ba28fd9c10bd702cfe98deb5'),('public.bump_integrated_dependency_v4()','56609f00083cbad9facdd2e3000900304a0af912b9ea2f31a6a1f70bbd3427f2'),('public.check_race_result_proof_head()','88a541a7126591a07291c0342ead6e550b1269a3195ea95768e5c5266174903e'),('public.check_race_result_proof_refs()','5912e5aac367ada6607e349a5ffce2bbc3947e08ca71126142e46fc86d9d1abc'),('public.course_deletion_terminal()','a34834f99abe0ca0214f1e5d58277ef35478702fed34374b4958bf325429bb30'),('public.course_lineage_allowed()','26e4c82a3fc8d09584274e6c4340004cc39382000f7a9c842c76e6f133442e14'),('public.enqueue_course_thumbnail_render()','bdc9b8575ff4ca56d4d1d7fa02ab71eb0aa603c8fbbeadbcc51e743f8a7b7f32'),('public.guard_app_binding_insert()','dd8e7e8ad12b5a6c8311b6a5e8d64a7eeaf6a2513a03a24a3e5236c06f35c37c'),('public.guard_nutrition_disconnection_insert()','ebdd671564aee5ca037d7d0c27bbbbe40a38ca2e3de997e5f804f7d7d6c888b8'),('public.guard_nutrition_disconnection_insert_before_lineage()','eb9e0c914df293e6668c4be96bc4f7b45d4bfe62627d7969868297ba39115dd4'),('public.guard_nutrition_integrated_copy_insert()','5c96ec9205ba8b3effa1d6ebddc174fbec93a50ebfe28638dc13844bb5f1d2bd'),('public.guard_nutrition_lineage_insert()','1ff65db8c091bd585e65eaaa24dde920152ffd5d424805bb6e701ca54673e186'),('public.guard_nutrition_save_receipt_copy()','794a2843298d1d3e2606ce3af0ad87f9b91619671d1fb8f1e386b6299e70e098'),('public.guard_nutrition_v4_receipt()','c232f3dd5e432d1d6c8d5609e398fce2851c7b7f34a728b7ba3672f658f7dde0'),('public.guard_nutrition_v4_seal()','fe2afe9114bb069986f3482fd792c9a6ce09e19f35706c4acf30df5e51576e5b'),('public.guard_race_head_deletion()','f1bbebed2a2b3e0adbdac7559878a0976f4601e08feb05129709e525122dcd09'),('public.guard_race_result_proof_body()','84028db772f3e3a55