.purge_healthkit_workouts_on_withdrawal()','59908f6fb0ea7dacc5f408d437f437b72998c4ebfabd1f16cfe390fb3a07f340'),('public.record_ai_consent_transition_suppression_event()','b7c7a7b8a57e990876c62aa9f3ccef7579da74e0834753775d2d7ffb7c9dd345'),('public.record_app_consent_transition_suppression_event()','25e90ed767b4d57becff8b55e7ceec2d5136a04a693fdbdc8d2d00c2ccd46324'),('public.record_healthkit_consent_transition_suppression_event()','3e4fc55c9ec9cfd26736df67bd34e9bf4c7cf3697369ca2514f708c99bc4ecf0'),('public.record_tenant_erasure_suppression_event()','f5630769ea8c2673abc541af3b2d715e3e961857d53dd2eb6c5fb9357480e8ca'),('public.redact_races_after_activity_deletion()','9542749610394645c5061b15e2289306c591919df711fc811beed3e316c90f5c'),('public.reject_coaching_candidate_parent_cycle()','7f3997635edda7db443c553c423c3963bb14ba6645a112f5e708abaac24654df'),('public.reject_pending_healthkit_reentry()','609a99bc4a46e24e0467ea95fa4a8c55dd42613330f2eecb3582a5655238ca42'),('public.resource_ai_consent_withdrawn()','31075e31daa8b260e647ecfe59095ba3827f0ef9ac4e26e06e7beaaabc27c2b2'),('public.resource_reviewed_insert_valid()','e83242410944918968b1307e4655fd35af1d34c73d5f63bda4a52a02f3bece40'),('public.resource_version_source_kind_valid()','ffb66d754ffc5ba30bf974b542dd3547b2759e34871651b58289966d83b6e2bc'),('public.restore_replay_erasure_time()','3262eb59b6efbbfcad7e9d29b1e2148c648f9bed80a46d08c0b55050cee7719f'),('public.suppress_healthkit_existing_binding_on_source_suppression()','65e7e3a68f54c780cfc88e5b636557c4af3d06f6c76b041afe04441e8021b0c8'),('public.sync_race_result_proof_refs()','986867ddcd26a8f19b57031684435d01167440a3b586ca8ace12eeae6f2940d2'),('public.validate_supplementary_session_link()','6fd568e57504e89e3d5d5cf1bbefe442139b71b91cea0603b16909bf4235bf0f'),('public.verify_app_consent_event_fields()','98dfd9acc3264dba6407319090a12c81245ada259804ce190290c260b8520381'),('public.verify_manual_race_v2_event_transition()','bf63974084c86e91c68fb58e36db1fb84e309cc3aa5f735ae2d75c02c5d9b86f'),('public.verify_manual_review_source_event_fields()','7e23e28657e818dec076a8766a25625d549e973397075984e75c2a4da14f3d87'),('public.verify_nutrition_disconnection()','619a7432333758dc989a3937960d0401604d0a2743ea42e3dd3d4303a4872935'),('public.verify_nutrition_integrated_marker()','8d2be50786158ca4cdd4ce9c1718635ae1f6345dfb6a13dd80d537b5efd943bc'),('public.verify_nutrition_v4_commit_final()','cd4c831932c5f39dd89e159a6b7b0d82b379b479005134df64978d40cf333c47'),('public.verify_restore_share_cause()','00b2d04451def60d2c248c643a9ce619d44016dbd6884734a860dc8576f0ac30'),('wm_app_load.family_capture()','8e7007e88746d1a8901613ef8449bd9e2a3083b4c880ac099a78dc42c1e1f310')) allowed(signature,expected_hash) LOOP
  oid_value:=signature::regprocedure::oid;
  SELECT pg_get_functiondef(oid_value),prosecdef,proconfig,proowner,proacl INTO r FROM pg_proc WHERE oid=oid_value;
  original:=r.pg_get_functiondef;
  IF wm_current_app_load.hash_json(to_jsonb(original)) IS NULL OR encode(sha256(convert_to(original,'UTF8')),'hex')<>expected_hash THEN RAISE EXCEPTION 'CURRENT_LOAD_OLD_BRANCH_PIN_REJECTED: %',signature; END IF;
  start_body:=strpos(original,'AS $function$');
  begin_at:=strpos(upper(substr(original,start_body)),'BEGIN');
  IF start_body=0 OR begin_at=0 THEN RAISE EXCEPTION 'CURRENT_LOAD_OLD_BRANCH_LANGUAGE_REJECTED'; END IF;
  begin_at:=start_body+begin_at-1;
  amended:=substr(original,1,begin_at+4)||E'\n IF TG_OP=''INSERT'' THEN\n  IF session_user=pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=''wm_current_app_load.target''::regclass)) THEN\n   IF wm_current_app_load.exact_loading_row(TG_TABLE_SCHEMA,TG_TABLE_NAME,to_jsonb(NEW)) THEN RETURN NEW; END IF;\n  END IF;\n END IF;\n'||substr(original,begin_at+5);
  IF signature IN ('public.guard_nutrition_v4_receipt()','public.manual_race_v2_guard_mutation()') THEN
   IF signature='public.guard_nutrition_v4_receipt()' AND NOT r.prosecdef THEN RAISE EXCEPTION 'CURRENT_LOAD_SEAL_GUARD_OWNER_REQUIRED'; END IF;
   IF signature='public.guard_nutrition_v4_receipt()' THEN
    amended:=replace(amended,E'\n END IF;\n'||substr(original,begin_at+5),E'\n END IF;\n IF TG_OP=''INSERT'' AND EXISTS(SELECT 1 FROM wm_current_app_load.historical_seal h WHERE h.relation_name=''nutrition_v4_commit_seal'' AND h.athlete_id=to_jsonb(NEW)->>''athlete_id'' AND h.primary_key->>1=to_jsonb(NEW)->''result''->>''versionId'') THEN RAISE EXCEPTION ''CURRENT_LOAD_HISTORICAL_SEAL_NOT_FRESH'' USING ERRCODE=''42501''; END IF;\n'||substr(original,begin_at+5));
   ELSE
    amended:=replace(amended,E'\n END IF;\n'||substr(original,begin_at+5),E'\n END IF;\n IF TG_OP=''INSERT'' AND current_user=pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=''wm_current_app_load.target''::regclass)) THEN IF EXISTS(SELECT 1 FROM wm_current_app_load.historical_seal h WHERE h.relation_name=''manual_race_chain_commit_v2'' AND h.athlete_id=to_jsonb(NEW)->>''athlete_id'' AND h.primary_key->>1=coalesce(to_jsonb(NEW)->>''evidence_id'',to_jsonb(NEW)->>''id'')) THEN RAISE EXCEPTION ''CURRENT_LOAD_HISTORICAL_SEAL_NOT_FRESH'' USING ERRCODE=''42501''; END IF; END IF;\n'||substr(original,begin_at+5));
   END IF;
  END IF;
  EXECUTE amended;
  SELECT prosecdef,proconfig,proowner,proacl INTO a FROM pg_proc WHERE oid=oid_value;
  IF a.prosecdef IS DISTINCT FROM r.prosecdef OR a.proconfig IS DISTINCT FROM r.proconfig OR a.proowner IS DISTINCT FROM r.proowner OR a.proacl IS DISTINCT FROM r.proacl THEN RAISE EXCEPTION 'CURRENT_LOAD_OLD_BRANCH_METADATA_CHANGED'; END IF;
  INSERT INTO wm_current_app_load.successor_metadata VALUES(signature,expected_hash,r.prosecdef,r.proconfig,r.proowner,r.proacl);
 END LOOP;
END $successors$;

CREATE FUNCTION wm_current_app_load.dependencies_ready(t text,v jsonb) RETURNS boolean
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
DECLARE p jsonb:=wm_current_app_load.relation(t); fk record; pair record; q text; nullable boolean; found boolean; BEGIN
 FOR fk IN SELECT c.*,n.nspname AS parent_schema,cl.relname AS parent_table FROM pg_constraint c JOIN pg_class cl ON cl.oid=c.confrelid JOIN pg_namespace n ON n.oid=cl.relnamespace
  WHERE c.conrelid=format('%I.%I',p->>'schema',p->>'table')::regclass AND c.contype='f' AND NOT c.condeferrable LOOP
  q:=''; nullable:=false;
  FOR pair IN SELECT child.attname AS child_column,parent.attname AS parent_column FROM unnest(fk.conkey,fk.confkey) a(child_num,parent_num)
   JOIN pg_attribute child ON child.attrelid=fk.conrelid AND child.attnum=a.child_num JOIN pg_attribute parent ON parent.attrelid=fk.confrelid AND parent.attnum=a.parent_num LOOP
   IF v->pair.child_column='null'::jsonb THEN nullable:=true; END IF;
   q:=q||CASE WHEN q='' THEN '' ELSE ' AND ' END||format('to_jsonb(parent)->>%L=$1->>%L',pair.parent_column,pair.child_column);
  END LOOP;
  IF NOT nullable THEN
   EXECUTE format('SELECT EXISTS(SELECT 1 FROM %I.%I parent WHERE %s)',fk.parent_schema,fk.parent_table,q) INTO found USING v;
   IF NOT found THEN RETURN false; END IF;
  END IF;
 END LOOP;
 RETURN true;
END $$;
CREATE FUNCTION wm_current_app_load.load_family(run uuid) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' SET DateStyle='ISO,YMD' AS $$
DECLARE d wm_current_app_load.descriptor; s wm_current_app_load.row_stage; p jsonb; n bigint; progress boolean;
 existing jsonb; predicate text; keys text[]; key text; BEGIN
 d:=wm_current_app_load.assert_context(run);
 IF NOT d.sealed OR d.loaded OR d.finished THEN RAISE EXCEPTION 'CURRENT_LOAD_SEALED_REQUIRED'; END IF;
 UPDATE wm_current_app_load.descriptor SET loading=true WHERE run_id=run;
 SET CONSTRAINTS ALL DEFERRED;
 LOOP
  SELECT count(*) INTO n FROM wm_current_app_load.row_stage WHERE run_id=run AND NOT consumed;
  EXIT WHEN n=0;
  progress:=false;
  FOR s IN SELECT stage.* FROM wm_current_app_load.row_stage stage WHERE run_id=run AND NOT consumed
   ORDER BY CASE WHEN relation_name='identity_private.account' THEN 0 WHEN relation_name='restore_suppression_event' THEN 1 ELSE 2 END,
    (wm_current_app_load.relation(relation_name)->>'rank')::int,ordinal LOOP
   p:=wm_current_app_load.relation(s.relation_name);
   IF NOT wm_current_app_load.dependencies_ready(s.relation_name,s.physical_row) THEN CONTINUE; END IF;
   SELECT array_agg(a.attname ORDER BY k.n) INTO keys FROM pg_constraint c CROSS JOIN LATERAL unnest(c.conkey) WITH ORDINALITY k(attnum,n)
    JOIN pg_attribute a ON a.attrelid=c.conrelid AND a.attnum=k.attnum WHERE c.conrelid=format('%I.%I',p->>'schema',p->>'table')::regclass AND c.contype='p';
   predicate:='';
   FOREACH key IN ARRAY keys LOOP predicate:=predicate||CASE WHEN predicate='' THEN '' ELSE ' AND ' END||format('to_jsonb(existing)->>%L=$1->>%L',key,key); END LOOP;
   EXECUTE format('SELECT to_jsonb(existing) FROM %I.%I existing WHERE %s',p->>'schema',p->>'table',predicate) INTO existing USING s.physical_row;
   IF existing IS NOT NULL THEN
    IF wm_current_app_load.encode_row(s.relation_name,existing) IS DISTINCT FROM s.physical_row THEN RAISE EXCEPTION 'CURRENT_LOAD_EXISTING_ROW_CONFLICT'; END IF;
   ELSE
    EXECUTE format('INSERT INTO %I.%I SELECT r.* FROM jsonb_populate_record(NULL::%I.%I,$1) r',p->>'schema',p->>'table',p->>'schema',p->>'table') USING s.physical_row;
   END IF;
   IF s.relation_name IN ('nutrition_v4_commit_seal','manual_race_chain_commit_v2') THEN
    INSERT INTO wm_current_app_load.historical_seal VALUES(s.relation_name,d.athlete_id,s.primary_key,s.row_digest,run) ON CONFLICT DO NOTHING;
   END IF;
   UPDATE wm_current_app_load.row_stage SET consumed=true WHERE run_id=run AND ordinal=s.ordinal;
   progress:=true;
  END LOOP;
  IF NOT progress THEN RAISE EXCEPTION 'CURRENT_LOAD_NONDEFERRABLE_DEPENDENCY_MISSING'; END IF;
 END LOOP;
 SET CONSTRAINTS ALL IMMEDIATE;
 UPDATE wm_current_app_load.descriptor SET loaded=true WHERE run_id=run;
END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA wm_current_app_load FROM PUBLIC;

-- Original rows are authenticated by the host's separate tail handle. SQL only
-- rechecks their exact installed tuple and invokes the existing owner replay ports.
-- Unsupported original families fail closed; no event or timestamp is minted here.
CREATE FUNCTION wm_current_app_load.post_replay(run uuid) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' SET DateStyle='ISO,YMD' AS $$
DECLARE d wm_current_app_load.descriptor; staged wm_current_app_load.row_stage;
 e public.restore_suppression_event; outcome text; BEGIN
 d:=wm_current_app_load.assert_context(run);
 IF NOT d.loaded OR d.post_replayed OR d.finished THEN RAISE EXCEPTION 'CURRENT_LOAD_LOADED_REQUIRED'; END IF;
 -- Run queued archive row checks while the exact stage still exists. These are
 -- restore-row correspondence checks, not a fresh commit seal or user admission.
 SET CONSTRAINTS ALL IMMEDIATE;
 FOR staged IN SELECT s.* FROM wm_current_app_load.row_stage s WHERE s.run_id=run
  AND s.relation_name='restore_suppression_event' ORDER BY (s.physical_row->>'occurred_at'),s.physical_row->>'event_id' LOOP
  SELECT * INTO STRICT e FROM public.restore_suppression_event WHERE event_id=(staged.physical_row->>'event_id')::uuid;
  IF wm_current_app_load.encode_row('restore_suppression_event',to_jsonb(e))<>staged.physical_row OR e.athlete_id<>d.athlete_id THEN RAISE EXCEPTION 'CURRENT_LOAD_ORIGINAL_EVENT_REJECTED'; END IF;
  IF e.record_version=4 AND e.kind IN ('race_event_deleted','race_result_deleted','training_best_deleted') THEN
   outcome:=public.replay_race_deletion_exact(e.athlete_id,e.kind,e.target_id,e.event_id,e.occurred_at,e.race_previous_revision,e.race_deleted_revision);
  ELSIF e.record_version=6 AND e.kind='manual_review_source_suppressed' THEN
   outcome:=public.replay_manual_review_source_suppression_exact(e.athlete_id,e.event_id,e.occurred_at,e.manual_review_source_kind,e.manual_review_source_id,e.manual_review_version_scope,e.manual_review_version_key);
  ELSIF e.record_version=7 AND e.kind='manual_review_source_suppressed_v2' THEN
   -- Original7 was installed from the sealed original roster. No live transition
   -- or new owner event is fabricated by this already-applied posthook.
   PERFORM public.suppress_manual_race_chain_from_event_v2(e.event_id);
   outcome:='already_applied';
  ELSIF e.record_version=1 AND e.kind='course_deleted' THEN
   outcome:=public.replay_course_deletion_exact(e.athlete_id,e.target_id,e.event_id,e.occurred_at);
  ELSIF e.record_version=1 AND e.kind='activity_deleted' THEN
   outcome:=public.replay_activity_deletion_exact(e.athlete_id,e.target_id,e.event_id,e.occurred_at,e.activity_revision,e.source_kind,e.source_id,e.source_revision,e.source_content_hash);
  ELSIF e.record_version=1 AND e.kind='resource_deleted' THEN
   -- Compound resource/share originals require their separately authenticated
   -- child roster. A child-only original must never silently discard it.
   IF EXISTS(SELECT 1 FROM public.restore_suppression_event child WHERE child.share_cause_event_id=e.event_id) THEN RAISE EXCEPTION 'CURRENT_LOAD_COMPOUND_ORIGINAL_PORT_MISSING'; END IF;
   outcome:=public.replay_resource_deletion_exact(e.athlete_id,e.target_id,e.event_id,e.occurred_at,e.resource_access_revision);
  ELSIF e.record_version=1 AND e.kind='gallery_media_deleted' THEN
   outcome:=public.replay_gallery_media_deletion_exact(e.athlete_id,e.target_id,e.event_id,e.occurred_at,e.gallery_access_revision);
  ELSIF e.record_version=1 AND e.kind='check_in_deleted' THEN
   outcome:=public.replay_check_in_deletion_exact(e.athlete_id,e.target_id,e.event_id,e.occurred_at,e.check_in_revision);
  ELSIF e.record_version=5 AND e.kind='app_consent_transition' THEN
   outcome:=public.replay_app_consent_transition_exact(e.athlete_id,e.event_id,e.occurred_at,e.consent_previous_revision,e.consent_previous_granted,e.consent_revision,e.consent_granted);
  ELSE
   RAISE EXCEPTION 'CURRENT_LOAD_ORIGINAL_FAMILY_PORT_MISSING: %/%',e.record_version,e.kind;
  END IF;
  IF outcome NOT IN ('applied','already_applied','transitioned','already_applied_by_erasure') THEN RAISE EXCEPTION 'CURRENT_LOAD_ORIGINAL_REPLAY_REJECTED'; END IF;
  -- Every actual original, including an already installed original4, suppresses
  -- restored schema2 copied bodies using the original event's exact namespaces.
  PERFORM public.suppress_manual_race_chain_from_event_v2(e.event_id);
 END LOOP;
 SET CONSTRAINTS ALL IMMEDIATE;
 UPDATE wm_current_app_load.descriptor SET post_replayed=true WHERE run_id=run;
END $$;
CREATE FUNCTION wm_current_app_load.finish_stage(run uuid) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
DECLARE d wm_current_app_load.descriptor; BEGIN
 d:=wm_current_app_load.assert_context(run);
 IF NOT d.loaded OR NOT d.post_replayed OR d.finished OR EXISTS(SELECT 1 FROM wm_current_app_load.row_stage WHERE run_id=run AND NOT consumed) THEN RAISE EXCEPTION 'CURRENT_LOAD_POST_REPLAY_REQUIRED'; END IF;
 -- Force every deferred check before revoking the live restore-row branch. The
 -- descriptor and rows survive COMMIT for diagnostics and immutable provenance.
 SET CONSTRAINTS ALL IMMEDIATE;
 UPDATE wm_current_app_load.descriptor SET finished=true,loading=false WHERE run_id=run;
END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA wm_current_app_load FROM PUBLIC;
